INSERT INTO public.permisos (id, nombre, descripcion, activo, created_at) VALUES (5, 'inscripciones:gestionar', 'Ver y gestionar inscripciones: cambiar estado académico, exportar listas.', TRUE, '2026-04-29T00:35:50.363Z');
INSERT INTO public.permisos (id, nombre, descripcion, activo, created_at) VALUES (6, 'pagos:ver', 'Consultar historial de pagos, comprobantes y estado financiero. Solo lectura.', TRUE, '2026-04-29T00:35:50.363Z');
INSERT INTO public.permisos (id, nombre, descripcion, activo, created_at) VALUES (7, 'reportes:ver', 'Generar y descargar reportes del sistema. Solo lectura.', TRUE, '2026-04-29T00:35:50.363Z');
INSERT INTO public.permisos (id, nombre, descripcion, activo, created_at) VALUES (9, 'usuario:estudiante', 'Acceso completo a funcionalidades de estudiante: ver catálogo, inscribirse, ver y realizar pagos, ver calificaciones y cursos propios.', TRUE, '2026-04-29T13:18:10.469Z');
