INSERT INTO public.permisos (id, nombre, descripcion, activo, created_at) VALUES (17, 'logs_seguridad:ver', 'Consultar el registro de accesos, logins, bloqueos y desbloqueos. Solo lectura.', TRUE, '2026-05-27T04:21:41.194Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (1, 'RC-001', '3+ intentos fallidos de login consecutivos', 'El usuario o un atacante intenta ingresar más de 3 veces seguidas con credenciales inválidas.', 'Posible ataque de fuerza bruta contra cuentas de usuario', 3, 3, 9, 'CRITICO', 'Sistema de autenticación / Middleware de login', 'Bloquear cuenta al 3er intento, registrar IP, notificar al admin, activar CAPTCHA', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (2, 'RC-002', 'Login exitoso desde país/IP completamente diferente al habitual', 'Inicio de sesión correcto pero desde una ubicación geográfica/IP distinta a la que el usuario usa normalmente.', 'Credenciales posiblemente robadas y usadas desde otra ubicación', 2, 3, 6, 'CRITICO', 'Sistema de sesiones / Módulo de login', 'Verificar con 2FA, alertar al usuario por email, registrar evento en log de seguridad', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (3, 'RC-003', 'Creación de usuario con rol ADMIN fuera de horario laboral (10pm-6am)', 'Se crea un usuario con privilegios administrativos en horario inusual.', 'Posible escalada de privilegios no autorizada', 2, 3, 6, 'CRITICO', 'Módulo ABM de usuarios / Log de auditoría', 'Requerir doble aprobación para roles admin, alertar a todos los admins existentes', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (4, 'RC-004', 'Acceso a ruta/endpoint sin los permisos correspondientes', 'Un usuario intenta acceder a un endpoint para el cual no tiene autorización.', 'Intento de bypass de autorización o escalada horizontal de privilegios', 3, 3, 9, 'CRITICO', 'Middleware de autorización / Matriz de roles', 'Retornar 403, registrar IP y usuario, bloquear si ocurre 5+ veces en 10 min', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (5, 'RC-005', 'Token JWT modificado o expirado siendo reutilizado', 'Se presenta un token cuya firma no valida o que ya está vencido.', 'Intento de falsificación de sesión o session hijacking', 2, 3, 6, 'ALTO', 'Middleware de validación de tokens', 'Invalidar token, cerrar sesión forzosamente, registrar intento en log', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (6, 'RC-006', 'Cambio de rol de usuario sin seguir el flujo de aprobación', 'Se modifica el rol de un usuario sin pasar por el proceso de aprobación establecido.', 'Manipulación directa de permisos, posible insider threat', 2, 2, 4, 'ALTO', 'Módulo de gestión de roles', 'Todo cambio de rol debe pasar por aprobación, registrar quién hizo el cambio y cuándo', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (7, 'RC-007', 'Error 500 repetido (+3 veces) en el mismo endpoint en menos de 5 min', 'El mismo endpoint genera errores 500 múltiples veces en poco tiempo.', 'Posible vulnerabilidad siendo explotada activamente', 2, 3, 6, 'ALTO', 'Manejador global de excepciones', 'Alertar a dev team, revisar logs del endpoint, considerar deshabilitar temporalmente', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (8, 'RC-008', 'Upload de archivo con extensión ejecutable (.php, .exe, .sh, .py)', 'Un usuario intenta subir archivos con extensiones potencialmente peligrosas.', 'Posible intento de subir webshell o malware al servidor', 2, 3, 6, 'ALTO', 'Módulo de carga de archivos', 'Rechazar extensiones peligrosas, validar MIME type real, escanear con antivirus', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (9, 'RC-009', 'Más de 100 peticiones al mismo endpoint en menos de 1 minuto', 'Un mismo origen genera un volumen inusualmente alto de peticiones.', 'Posible ataque DDoS, scraping masivo o fuzzing de parámetros', 2, 2, 4, 'ALTO', 'Rate limiter / API Gateway', 'Implementar rate limiting, bloquear IP temporalmente, registrar en log', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (10, 'RC-010', 'Usuario inactivo por 6+ meses que inicia sesión repentinamente', 'Una cuenta sin actividad reciente se reactiva sin previo aviso.', 'Cuenta zombie reactivada, posible uso de credenciales antiguas filtradas', 2, 2, 4, 'MEDIO', 'Sistema de autenticación / Gestión de sesiones', 'Forzar cambio de contraseña, verificar identidad, revisar actividad previa', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (11, 'RC-011', 'Descarga masiva de registros (+50 registros) en una sola petición', 'Un usuario solicita una cantidad anormalmente grande de registros.', 'Posible exfiltración de datos de la base de datos', 2, 2, 4, 'MEDIO', 'Controladores de listado / API de datos', 'Limitar resultados por página, requerir permisos especiales para exportación masiva', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (12, 'RC-012', 'Múltiples cambios de perfil en menos de 2 minutos', 'Un mismo usuario modifica su perfil varias veces en muy poco tiempo.', 'Comportamiento automatizado o script modificando datos', 1, 2, 2, 'MEDIO', 'Módulo de gestión de perfil', 'Cooldown entre cambios, CAPTCHA si se detecta patrón automatizado', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (13, 'RC-013', 'Sesión activa por más de 8 horas sin actividad', 'Un token válido sigue activo después de muchas horas sin uso.', 'Token no invalidado, posible sesión abandonada en equipo compartido', 2, 2, 4, 'MEDIO', 'Middleware de sesiones', 'Timeout automático de sesión, invalidar token después de X minutos de inactividad', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (14, 'RC-014', 'Login exitoso a las 3am - 5am', 'Inicio de sesión correcto pero en horario poco común.', 'Inusual pero no necesariamente malicioso, se monitorea', 1, 1, 1, 'BAJO', 'Sistema de autenticación', 'Registrar en log, generar alerta baja, revisar si se repite el patrón', TRUE, '2026-05-26T21:33:11.742Z');
INSERT INTO public.riesgo_catalogo (id, codigo, nombre, descripcion, por_que_sospechoso, probabilidad, impacto, nivel_riesgo, nivel_categoria, quien_detecta, control_implementar, activo, fecha_creacion) VALUES (15, 'RC-015', 'Cambio de contraseña sin solicitud previa del usuario', 'Se modifica la contraseña sin que el usuario haya solicitado un reset.', 'Puede indicar que alguien más tiene acceso a la cuenta', 1, 2, 2, 'BAJO', 'Módulo de gestión de contraseñas', 'Notificar al usuario por email/SMS, ofrecer opción de revertir y bloquear', TRUE, '2026-05-26T21:33:11.742Z');
