INSERT INTO public.riesgos_matriz (id, activo_informacion, amenazas, fecha_registro) VALUES (6, 'Base de Datos de Inscripciones y Calificaciones', '[{"id":"t_ins_01","plan_accion":["Auditar código de endpoints de inscripciones usando herramientas de análisis estático (SAST).","Configurar reglas de Web Application Firewall (WAF) para bloquear payloads maliciosos.","Implementar verificación criptográfica de integridad de registros de inscripciones."],"control_tipo":"P, D","fecha_limite":"2026-06-15","control_nivel":"A","responsable_id":45,"riesgo_residual":5,"impacto_residual":5,"riesgo_inherente":15,"impacto_inherente":5,"control_frecuencia":"PT","responsable_nombre":"Christian Coronel","tratamiento_riesgo":"Reducir","consecuencia_riesgo":"Alteración de registros académicos, inscripciones fraudulentas de estudiantes sin pago, y pérdida de integridad y confiabilidad de los datos académicos.","controles_implementar":"Implementar ORM con consultas parametrizadas, middleware de validación estricta de tokens JWT, y auditoría obligatoria de todos los cambios en tablas de inscripciones (log de aplicación).","nivel_riesgo_residual":"Moderado","probabilidad_residual":1,"amenaza_vulnerabilidad":"Inyección SQL o explotación de fallos de autorización en el endpoint de actualización de inscripciones","nivel_riesgo_inherente":"Alto","probabilidad_inherente":3}]'::jsonb, '2026-05-27T05:34:39.380Z');
INSERT INTO public.riesgos_matriz (id, activo_informacion, amenazas, fecha_registro) VALUES (7, 'Credenciales de API de Pagos (Paypal / Pasarela)', '[{"id":"t_ins_02","plan_accion":["Rotar las llaves de API de Paypal de producción cada 90 días de forma automatizada.","Implementar la verificación de la firma del webhook con la clave secreta proporcionada por Paypal.","Configurar alertas críticas ante cualquier intento fallido de validación de firma de webhook."],"control_tipo":"P, D","fecha_limite":"2026-07-01","control_nivel":"A","responsable_id":64,"riesgo_residual":5,"impacto_residual":5,"riesgo_inherente":10,"impacto_inherente":5,"control_frecuencia":"PT","responsable_nombre":"Alessandro Lopez","tratamiento_riesgo":"Reducir","consecuencia_riesgo":"Pérdida económica por inscripciones validadas con transacciones falsas, exfiltración de credenciales financieras del sistema, y daño reputacional a la institución.","controles_implementar":"Almacenamiento seguro de secretos usando variables de entorno cifradas (Supabase vault/dotenv cifrado), validación criptográfica de firmas de webhooks de Paypal, y rate limiting estricto.","nivel_riesgo_residual":"Moderado","probabilidad_residual":1,"amenaza_vulnerabilidad":"Fuga de API Keys de producción o manipulación del webhook de confirmación de pagos de Paypal","nivel_riesgo_inherente":"Alto","probabilidad_inherente":2}]'::jsonb, '2026-05-27T05:34:39.380Z');
